/*
 * VelaWear Agent - Audio Sensor Driver
 *
 * The Huangshan Pi has an onboard MEMS microphone wired to the SF32LB52
 * AUDCODEC ADC.  This board port does not register /dev/audio/pcm_in0, so
 * microphone bring-up uses the direct AUDCODEC DMA diagnostic path.
 *
 * Author: pjjuihj
 * Team: 329 - dela
 */

#include <nuttx/config.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>

#include "velawear.h"
#include "../audio_hw_test.h"

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int audio_sensor_init(velawear_audio_t *audio)
{
  int ret;

  memset(audio, 0, sizeof(velawear_audio_t));

  audio->fd = -1;
  audio->sample_rate = 16000;
  audio->initialized = false;

  /*
   * Probe the actual onboard MEMS microphone path.  The finite probe uses
   * HAL_AUDCODEC_Receive_DMA and returns only after the ADC path has either
   * produced a complete sample buffer or reported an error.
   */
  syslog(LOG_INFO,
         "[Audio] Probing onboard MEMS microphone via direct AUDCODEC ADC\n");
  ret = velawear_mic_hw_test();
  if (ret != 0)
    {
      syslog(LOG_WARNING,
             "[Audio] Onboard MEMS microphone ADC probe failed: %d\n", ret);
      return VELAWEAR_ERR_IO;
    }

  audio->initialized = true;
  syslog(LOG_INFO,
         "[Audio] Onboard MEMS microphone ready via direct AUDCODEC ADC at %d Hz\n",
         audio->sample_rate);
  return VELAWEAR_OK;
}

void audio_sensor_cleanup(velawear_audio_t *audio)
{
  if (audio->fd >= 0)
    {
      close(audio->fd);
      audio->fd = -1;
    }

  audio->initialized = false;
  syslog(LOG_INFO, "[Audio] Cleaned up\n");
}

