   777	  ret = velawear_retry_imu(agent);
   778	  if (ret < 0)
   779	    {
   780	      syslog(LOG_WARNING, "[VelaWear] IMU sensor init failed after retry: %d\n",
   781	             ret);
   782	      velawear_set_degradation_mode(agent, VELAWEAR_MODE_INDEPENDENT,
   783	                                     "imu unavailable");
   784	    }
   785	
   786	  ret = velawear_retry_audio(agent);
