   790	             "[VelaWear] Audio sensor init failed after retry: %d\n", ret);
   791	      syslog(LOG_WARNING,
   792	             "[Degrade] Microphone input unavailable; display/speaker actions remain\n");
   793	    }
   794	
   795	  /* Initialize LLM client */
   796	
   797	  ret = velawear_llm_init(&agent->llm);
   798	  if (ret < 0)
   799	    {
   800	      syslog(LOG_WARNING, "[VelaWear] LLM init failed: %d\n", ret);
   801	      velawear_set_degradation_mode(agent, VELAWEAR_MODE_INDEPENDENT,
