   810	  ret = event_manager_register_handler(&agent->events,
   811	                                       VELAWEAR_EVENT_NONE,
   812	                                       velawear_event_handler,
   813	                                       agent,
   814	                                       VELAWEAR_PRIORITY_NORMAL);
