   869	static int velawear_start(velawear_agent_t *agent)
   870	{
   871	  int ret;
   872	
   873	  /* The main loop owns event queue consumption.  Do not start a second
   874	   * consumer thread for the same mqueue. */
   875	
   876	  /* Start action manager thread. */
   877	
   878	  ret = action_manager_start(&agent->actions);
   879	  if (ret < 0)
   880	    {
   881	      syslog(LOG_ERR, "[VelaWear] Action manager start failed: %d\n", ret);
   882	      return ret;
   883	    }
   884	
   885	  /* Decision rules are evaluated synchronously for each event. */
   886	
   887	  /* Mark agent as running before starting the sensor producer. */
   888	
   889	  agent->running = true;
   890	  ret = velawear_watchdog_start(agent);
   891	  if (ret < 0)
   892	    {
   893	      agent->running = false;
   894	      return ret;
   895	    }
   896	
   897	  if (agent->imu.initialized)
   898	    {
   899	      ret = pthread_create(&agent->imu_thread, NULL,
   900	                           velawear_imu_thread, agent);
   901	      if (ret != 0)
   902	        {
   903	          agent->running = false;
   904	          syslog(LOG_ERR, "[VelaWear] IMU thread start failed: %d\n", ret);
   905	          return VELAWEAR_ERR_IO;
   906	        }
   907	      agent->imu_thread_started = true;
   908	    }
   909	  return VELAWEAR_OK;
   910	}
   911	
   912	static void velawear_cleanup(velawear_agent_t *agent)
   913	{
   914	  /* Stop subsystems in reverse order */
   915	
   916	  agent->running = false;
   917	  velawear_watchdog_stop(agent);
   918	  if (agent->imu_thread_started)
   919	    {
   920	      pthread_join(agent->imu_thread, NULL);
   921	      agent->imu_thread_started = false;
   922	    }
   923	
   924	  velawear_llm_cleanup(&agent->llm);
   925	  velawear_ble_cleanup();
   926	  audio_sensor_cleanup(&agent->audio);
   927	  imu_sensor_cleanup(&agent->imu);
   928	  action_manager_cleanup(&agent->actions);
   929	  event_manager_cleanup(&agent->events);
   930	  decision_engine_cleanup(&agent->engine);
   931	  velawear_buttons_close();
   932	  display_manager_cleanup(&agent->display);
   933	  state_manager_cleanup(&agent->state_mgr);
   934	  velawear_config_cleanup(&agent->config);
   935	}
