    55	static void *display_audio_worker(void *arg)
    56	{
    57	  velawear_display_t *display = (velawear_display_t *)arg;
    58	  uint8_t job;
    59	  int ret;
    60	
    61	  pthread_mutex_lock(&display->lock);
    62	  job = display->audio_job;
    63	  pthread_mutex_unlock(&display->lock);
    64	
    65	  if (job == DISPLAY_AUDIO_JOB_MIC)
    66	    {
    67	      ret = velawear_mic_hw_test();
    68	    }
    69	  else
    70	    {
    71	      ret = velawear_music_hw_test();
    72	    }
    73	
    74	  pthread_mutex_lock(&display->lock);
    75	  display->audio_test_result = ret;
    76	  display->audio_test_running = false;
    77	  pthread_mutex_unlock(&display->lock);
    78	  return NULL;
    79	}
    80	
    81	static int display_audio_start(velawear_display_t *display, uint8_t job)
    82	{
    83	  pthread_t finished_thread;
    84	  bool reap_finished = false;
    85	  int ret;
    86	
    87	  pthread_mutex_lock(&display->lock);
    88	  if (display->audio_test_running)
    89	    {
    90	      pthread_mutex_unlock(&display->lock);
    91	      return 1;
    92	    }
    93	
    94	  if (display->audio_thread_started)
    95	    {
    96	      finished_thread = display->audio_thread;
    97	      display->audio_thread_started = false;
    98	      reap_finished = true;
    99	    }
   100	
   101	  display->audio_job = job;
   102	  display->audio_test_result = -1;
   103	  display->audio_test_running = true;
   104	  pthread_mutex_unlock(&display->lock);
   105	
   106	  if (reap_finished)
   107	    {
   108	      pthread_join(finished_thread, NULL);
   109	    }
   110	
   111	  ret = pthread_create(&display->audio_thread, NULL,
   112	                       display_audio_worker, display);
   113	  if (ret != 0)
   114	    {
   115	      pthread_mutex_lock(&display->lock);
   116	      display->audio_test_running = false;
   117	      pthread_mutex_unlock(&display->lock);
   118	      syslog(LOG_ERR, "[Display] audio worker create failed: %d\n", ret);
   119	      return -1;
   120	    }
   121	
   122	  pthread_mutex_lock(&display->lock);
   123	  display->audio_thread_started = true;
   124	  pthread_mutex_unlock(&display->lock);
   125	  return 0;
   126	}
