   130	  pthread_t finished_thread;
   131	  uint8_t job = DISPLAY_AUDIO_JOB_NONE;
   132	  int ret = -1;
   133	  bool reap_finished = false;
   134	
   135	  pthread_mutex_lock(&display->lock);
   136	  if (display->audio_thread_started && !display->audio_test_running)
   137	    {
   138	      finished_thread = display->audio_thread;
   139	      job = display->audio_job;
   140	      ret = display->audio_test_result;
   141	      display->audio_thread_started = false;
   142	      reap_finished = true;
   143	    }
   144	  pthread_mutex_unlock(&display->lock);
   145	
   146	  if (!reap_finished)
   147	    {
   148	      return;
   149	    }
