   329	static void display_detail_action_cb(lv_event_t *event)
   330	{
   331	  velawear_display_t *display =
   332	    (velawear_display_t *)lv_event_get_user_data(event);
   333	  lv_obj_t *target = lv_event_get_target(event);
   334	  int action;
   335	  int ret;
   336	
   337	  if (display == NULL || target == NULL)
   338	    {
   339	      return;
   340	    }
   341	
   342	  action = (int)(uintptr_t)lv_obj_get_user_data(target);
   343	  lv_event_stop_bubbling(event);
   344	  ret = 0;
   345	
   346	  switch (action)
   347	    {
   348	      case DISPLAY_ACTION_AUDIO_SPEAKER:
   349	      case DISPLAY_ACTION_MUSIC_PLAY:
   350	        if (display->detail_hint != NULL)
   351	          {
   352	            lv_label_set_text(display->detail_hint, "正在播放测试旋律...");
   353	          }
   354	        ret = display_audio_start(display, DISPLAY_AUDIO_JOB_MELODY);
   355	        if (ret > 0 && display->detail_hint != NULL)
   356	          {
   357	            lv_label_set_text(display->detail_hint, "测试进行中...");
   358	          }
   359	        else if (ret < 0 && display->detail_hint != NULL)
   360	          {
   361	            lv_label_set_text(display->detail_hint, "测试启动失败");
   362	          }
   363	        break;
   364	
   365	      case DISPLAY_ACTION_AUDIO_MIC:
   366	        if (display->detail_hint != NULL)
   367	          {
   368	            lv_label_set_text(display->detail_hint, "正在采集麦克风...");
   369	          }
   370	        ret = display_audio_start(display, DISPLAY_AUDIO_JOB_MIC);
   371	        if (ret > 0 && display->detail_hint != NULL)
   372	          {
   373	            lv_label_set_text(display->detail_hint, "测试进行中...");
   374	          }
   375	        else if (ret < 0 && display->detail_hint != NULL)
   376	          {
   377	            lv_label_set_text(display->detail_hint, "测试启动失败");
   378	          }
   379	        break;
   380	
   381	      case DISPLAY_ACTION_STOP_START:
   382	        if (display->stopwatch_running)
   383	          {
   384	            display->stopwatch_elapsed_ms +=
   385	              display_now_ms() - display->stopwatch_started_ms;
   386	            display->stopwatch_running = false;
   387	          }
   388	        else
   389	          {
   390	            display->stopwatch_started_ms = display_now_ms();
   391	            display->stopwatch_running = true;
   392	          }
   393	        display->last_update_ms = 0;
   394	        break;
   395	
   396	      case DISPLAY_ACTION_STOP_RESET:
   397	        display->stopwatch_running = false;
   398	        display->stopwatch_started_ms = 0;
   399	        display->stopwatch_elapsed_ms = 0;
   400	        display->last_update_ms = 0;
   401	        break;
   402	
   403	      default:
   404	        break;
   405	    }
   406	}
