   408	static void display_gesture_cb(lv_event_t *event)
   409	{
   410	  velawear_display_t *display;
   411	  lv_indev_t *indev;
   412	  lv_dir_t dir = LV_DIR_NONE;
   413	  lv_point_t point = {0, 0};
   414	  velawear_event_t touch_event;
   415	  lv_event_code_t code;
   416	  int app_index;
   417	  int32_t dx;
   418	  int32_t dy;
   419	
   420	  display = (velawear_display_t *)lv_event_get_user_data(event);
   421	  indev = lv_indev_active();
   422	  if (display == NULL || indev == NULL || display->detail_active)
   423	    {
   424	      return;
   425	    }
   426	
   427	  code = lv_event_get_code(event);
   428	  lv_indev_get_point(indev, &point);
   429	  if (code == LV_EVENT_PRESSED)
   430	    {
   431	      display->touch_start = point;
   432	      display->touch_tracking = true;
   433	      display->touch_swipe_handled = false;
   434	    }
   435	  else if (code == LV_EVENT_GESTURE)
   436	    {
   437	      dir = lv_indev_get_gesture_dir(indev);
   438	      display->touch_swipe_handled = true;
   439	    }
   440	
   441	  memset(&touch_event, 0, sizeof(touch_event));
   442	  touch_event.type = VELAWEAR_EVENT_TOUCH;
   443	  touch_event.priority = VELAWEAR_PRIORITY_NORMAL;
   444	  touch_event.timestamp = display_now_ms();
   445	  touch_event.data.touch.x = point.x;
   446	  touch_event.data.touch.y = point.y;
   447	  touch_event.data.touch.gesture = code == LV_EVENT_GESTURE ?
   448	                                    (int)dir : (int)code;
   449	  if (display->events != NULL &&
   450	      event_manager_push(display->events, &touch_event) < 0)
   451	    {
   452	      syslog(LOG_WARNING, "[Display] Failed to queue touch event\n");
   453	    }
   454	
   455	  if (code == LV_EVENT_RELEASED)
   456	    {
   457	      dx = (int32_t)point.x - (int32_t)display->touch_start.x;
   458	      dy = (int32_t)point.y - (int32_t)display->touch_start.y;
   459	      if (display->touch_tracking && !display->touch_swipe_handled &&
   460	          (dx <= -40 || dx >= 40) &&
   461	          (dx < 0 ? -dx : dx) > (dy < 0 ? -dy : dy))
   462	        {
   463	          display->touch_swipe_handled = true;
   464	          if (dx < 0)
   465	            {
   466	              display_manager_next_page(display);
   467	            }
   468	          else
   469	            {
   470	              display_manager_previous_page(display);
   471	            }
   472	        }
   473	      display->touch_tracking = false;
   474	    }
   475	  else if (code == LV_EVENT_CLICKED)
   476	    {
   477	      if (display->touch_swipe_handled)
   478	        {
   479	          display->touch_swipe_handled = false;
   480	          return;
   481	        }
   482	
   483	      if (display->page_index == VELAWEAR_PAGE_APPS)
   484	        {
   485	          if (display->mvp_app_detail_active)
   486	            {
   487	              display->mvp_app_detail_active = false;
   488	              display->last_update_ms = 0;
   489	              return;
   490	            }
   491	
   492	          if (point.y >= 115 && point.y < 335)
   493	            {
   494	              app_index = ((int)point.y - 115) / 27;
   495	              if (app_index >= 0 && app_index < 8)
   496	                {
   497	                  display->mvp_selected_app = (uint8_t)app_index;
   498	                  display->mvp_app_detail_active = true;
   499	                  display->last_update_ms = 0;
   500	                }
   501	            }
   502	          return;
   503	        }
   504	
   505	      display_manager_set_page(display,
   506	                               display->page_index == VELAWEAR_PAGE_WATCHFACE ?
   507	                               VELAWEAR_PAGE_APPS : VELAWEAR_PAGE_WATCHFACE);
   508	    }
   509	  else if (code == LV_EVENT_LONG_PRESSED)
   510	    {
   511	      display->touch_swipe_handled = true;
   512	      display_manager_set_page(display, VELAWEAR_PAGE_WATCHFACE);
   513	    }
   514	  else if ((dir & LV_DIR_LEFT) != 0 || (dir & LV_DIR_TOP) != 0)
   515	    {
   516	      display_manager_next_page(display);
   517	    }
   518	  else if ((dir & LV_DIR_RIGHT) != 0 || (dir & LV_DIR_BOTTOM) != 0)
   519	    {
   520	      display_manager_previous_page(display);

