    87	static ssize_t velawear_ble_write_threshold(struct bt_conn *conn,
    88	                                            const struct bt_gatt_attr *attr,
    89	                                            const void *buf, uint16_t len,
    90	                                            uint16_t offset, uint8_t flags)
    91	{
    92	  const uint8_t *data = (const uint8_t *)buf;
    93	  uint16_t seconds;
    94	
    95	  (void)conn;
    96	  (void)attr;
    97	  if (buf == NULL || offset != 0 || len != sizeof(uint16_t) ||
    98	      (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0)
    99	    {
   100	      return -EINVAL;
   101	    }
   102	
   103	  seconds = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
   104	  if (seconds < 10 || seconds > 3600)
   105	    {
   106	      return -EINVAL;
   107	    }
