   109	  pthread_mutex_lock(&g_lock);
   110	  g_config->sedentary_threshold_sec = seconds;
   111	  pthread_mutex_unlock(&g_lock);
   112	  syslog(LOG_INFO, "[BLE] Sedentary threshold updated: %u s\n",
   113	         (unsigned int)seconds);
   114	  return len;
   115	}
