   128	  struct bt_conn *old_conn;
   129	  bool enabled = (value & BT_GATT_CCC_NOTIFY) != 0;
   130	
   131	  (void)attr;
   132	  old_conn = NULL;
   133	
   134	  pthread_mutex_lock(&g_lock);
   135	  old_conn = g_status_notify_conn;
   136	  g_status_notify_conn = enabled && conn != NULL ? bt_conn_ref(conn) : NULL;
   137	  g_status_notify_enabled = enabled;
   138	  pthread_mutex_unlock(&g_lock);
   139	
   140	  if (old_conn != NULL)
   141	    {
   142	      bt_conn_unref(old_conn);
   143	    }
   144	
   145	  if (enabled)
   146	    {
   147	      (void)k_work_submit(&g_status_notify_work);
   148	    }
   149	
   150	  return sizeof(value);
   151	}
